SET XACT_ABORT ON;
SET NOCOUNT ON;

DECLARE @CountryId INT = (SELECT Id FROM dbo.Countries WHERE Code = N'NIC');
IF @CountryId IS NULL THROW 50000, 'Nicaragua must exist before loading the territorial catalog.', 1;

DECLARE @AdministrativeLevels TABLE (DisplayName NVARCHAR(80) NOT NULL PRIMARY KEY, Id INT NOT NULL);
INSERT INTO @AdministrativeLevels (DisplayName, Id)
SELECT administrativeLevel.DisplayName, administrativeLevel.Id
FROM dbo.CountryAdministrativeLevels AS administrativeLevel
WHERE administrativeLevel.CountryId = @CountryId;

DECLARE @AdministrativeAreaTypes TABLE (Name NVARCHAR(80) NOT NULL PRIMARY KEY, Id INT NOT NULL);
INSERT INTO @AdministrativeAreaTypes (Name, Id)
SELECT areaType.Name, areaType.Id
FROM dbo.AdministrativeAreaTypes AS areaType
INNER JOIN dbo.CountryAdministrativeLevels AS administrativeLevel
    ON administrativeLevel.Id = areaType.CountryAdministrativeLevelId
WHERE administrativeLevel.CountryId = @CountryId;

IF (SELECT COUNT(*) FROM @AdministrativeLevels) < 11
    THROW 50000, 'Nicaragua administrative levels must exist before loading the territorial catalog.', 1;

IF (SELECT COUNT(*) FROM @AdministrativeAreaTypes) < 12
    THROW 50000, 'Nicaragua administrative area types must exist before loading the territorial catalog.', 1;

DECLARE @Municipalities TABLE (DepartmentCode NVARCHAR(30) NOT NULL, DepartmentName NVARCHAR(200) NOT NULL, MunicipalityCode NVARCHAR(30) NOT NULL, MunicipalityName NVARCHAR(200) NOT NULL, ParentLevelName NVARCHAR(80) NOT NULL, PRIMARY KEY (DepartmentCode, MunicipalityCode));

