BEGIN TRANSACTION;

INSERT INTO dbo.AdministrativeAreas (CountryAdministrativeLevelId, AdministrativeAreaTypeId, ParentId, Code, Name)
SELECT administrativeLevel.Id, areaType.Id, NULL, source.DepartmentCode, source.DepartmentName
FROM (SELECT DISTINCT DepartmentCode, DepartmentName, ParentLevelName FROM @Municipalities) AS source
INNER JOIN @AdministrativeLevels AS administrativeLevel ON administrativeLevel.DisplayName = source.ParentLevelName
INNER JOIN dbo.AdministrativeAreaTypes AS areaType ON areaType.CountryAdministrativeLevelId = administrativeLevel.Id AND areaType.Code = CASE source.ParentLevelName WHEN N'Departamento' THEN N'DEPARTMENT' ELSE N'REGION' END
WHERE NOT EXISTS (SELECT 1 FROM dbo.AdministrativeAreas AS target WITH (UPDLOCK, HOLDLOCK) WHERE target.CountryAdministrativeLevelId = administrativeLevel.Id AND target.ParentId IS NULL AND target.Code = source.DepartmentCode);

INSERT INTO dbo.AdministrativeAreas (CountryAdministrativeLevelId, AdministrativeAreaTypeId, ParentId, Code, Name)
SELECT municipalityLevel.Id, areaType.Id, parent.Id, source.MunicipalityCode, source.MunicipalityName
FROM @Municipalities AS source
INNER JOIN @AdministrativeLevels AS parentLevel ON parentLevel.DisplayName = source.ParentLevelName
INNER JOIN dbo.AdministrativeAreas AS parent ON parent.CountryAdministrativeLevelId = parentLevel.Id AND parent.ParentId IS NULL AND parent.Code = source.DepartmentCode
INNER JOIN @AdministrativeLevels AS municipalityLevel ON municipalityLevel.DisplayName = N'Municipio'
INNER JOIN dbo.AdministrativeAreaTypes AS areaType ON areaType.CountryAdministrativeLevelId = municipalityLevel.Id AND areaType.Code = N'MUNICIPALITY'
WHERE NOT EXISTS (SELECT 1 FROM dbo.AdministrativeAreas AS target WITH (UPDLOCK, HOLDLOCK) WHERE target.CountryAdministrativeLevelId = municipalityLevel.Id AND target.ParentId = parent.Id AND target.Code = source.MunicipalityCode);

COMMIT TRANSACTION;

CREATE TABLE #LocalAreas
(
    LoadOrder INT IDENTITY(1, 1) NOT NULL,
    DepartmentCode NVARCHAR(30) NOT NULL,
    MunicipalityCode NVARCHAR(30) NOT NULL,
    AdministrativeAreaTypeId INT NOT NULL,
    Name NVARCHAR(200) NOT NULL,
    CONSTRAINT PK_LocalAreas PRIMARY KEY CLUSTERED (LoadOrder),
    CONSTRAINT UQ_LocalAreas UNIQUE
        (DepartmentCode, MunicipalityCode, AdministrativeAreaTypeId, Name)
);

DECLARE @BarrioTypeId INT = (SELECT Id FROM @AdministrativeAreaTypes WHERE Name = N'Barrio');
IF @BarrioTypeId IS NULL THROW 50000, 'Administrative area type Barrio must exist before loading the territorial catalog.', 1;

DECLARE @ComarcaTypeId INT = (SELECT Id FROM @AdministrativeAreaTypes WHERE Name = N'Comarca');
IF @ComarcaTypeId IS NULL THROW 50000, 'Administrative area type Comarca must exist before loading the territorial catalog.', 1;

DECLARE @ComunidadTypeId INT = (SELECT Id FROM @AdministrativeAreaTypes WHERE Name = N'Comunidad');
IF @ComunidadTypeId IS NULL THROW 50000, 'Administrative area type Comunidad must exist before loading the territorial catalog.', 1;

DECLARE @LocalidadTypeId INT = (SELECT Id FROM @AdministrativeAreaTypes WHERE Name = N'Localidad');
IF @LocalidadTypeId IS NULL THROW 50000, 'Administrative area type Localidad must exist before loading the territorial catalog.', 1;

DECLARE @MicroregionTypeId INT = (SELECT Id FROM @AdministrativeAreaTypes WHERE Name = N'Microregion');
IF @MicroregionTypeId IS NULL THROW 50000, 'Administrative area type Microregion must exist before loading the territorial catalog.', 1;

DECLARE @RepartoTypeId INT = (SELECT Id FROM @AdministrativeAreaTypes WHERE Name = N'Reparto');
IF @RepartoTypeId IS NULL THROW 50000, 'Administrative area type Reparto must exist before loading the territorial catalog.', 1;

DECLARE @SectorTypeId INT = (SELECT Id FROM @AdministrativeAreaTypes WHERE Name = N'Sector');
IF @SectorTypeId IS NULL THROW 50000, 'Administrative area type Sector must exist before loading the territorial catalog.', 1;

DECLARE @ZonaTypeId INT = (SELECT Id FROM @AdministrativeAreaTypes WHERE Name = N'Zona');
IF @ZonaTypeId IS NULL THROW 50000, 'Administrative area type Zona must exist before loading the territorial catalog.', 1;

