DECLARE @LocalAreaBatchStart INT = 0;
DECLARE @LocalAreaBatchSize INT = 500;
DECLARE @LocalAreaMax INT = (SELECT MAX(LoadOrder) FROM #LocalAreas);

WHILE @LocalAreaBatchStart < @LocalAreaMax
BEGIN
    BEGIN TRANSACTION;

    INSERT INTO dbo.AdministrativeAreas (CountryAdministrativeLevelId, AdministrativeAreaTypeId, ParentId, Code, Name)
    SELECT administrativeLevel.Id, source.AdministrativeAreaTypeId, municipality.Id, source.Name, source.Name
    FROM #LocalAreas AS source
    INNER JOIN dbo.AdministrativeAreaTypes AS areaType ON areaType.Id = source.AdministrativeAreaTypeId
    INNER JOIN dbo.CountryAdministrativeLevels AS administrativeLevel ON administrativeLevel.Id = areaType.CountryAdministrativeLevelId
    INNER JOIN @Municipalities AS municipalitySource ON municipalitySource.DepartmentCode = source.DepartmentCode AND municipalitySource.MunicipalityCode = source.MunicipalityCode
    INNER JOIN @AdministrativeLevels AS parentLevel ON parentLevel.DisplayName = municipalitySource.ParentLevelName
    INNER JOIN dbo.AdministrativeAreas AS department ON department.CountryAdministrativeLevelId = parentLevel.Id AND department.ParentId IS NULL AND department.Code = source.DepartmentCode
    INNER JOIN @AdministrativeLevels AS municipalityLevel ON municipalityLevel.DisplayName = N'Municipio'
    INNER JOIN dbo.AdministrativeAreas AS municipality ON municipality.CountryAdministrativeLevelId = municipalityLevel.Id AND municipality.ParentId = department.Id AND municipality.Code = source.MunicipalityCode
    WHERE source.LoadOrder > @LocalAreaBatchStart
      AND source.LoadOrder <= @LocalAreaBatchStart + @LocalAreaBatchSize
      AND NOT EXISTS (SELECT 1 FROM dbo.AdministrativeAreas AS target WITH (UPDLOCK, HOLDLOCK) WHERE target.CountryAdministrativeLevelId = administrativeLevel.Id AND target.ParentId = municipality.Id AND target.Code = source.Name);

    COMMIT TRANSACTION;
    SET @LocalAreaBatchStart += @LocalAreaBatchSize;
END;

CREATE TABLE #CandidateLocations
(
    AdministrativeAreaId INT NOT NULL PRIMARY KEY CLUSTERED,
    DisplayName NVARCHAR(600) NOT NULL
);

;WITH AreaPaths AS
(
    SELECT
        area.Id AS AdministrativeAreaId,
        area.ParentId,
        CAST(CASE WHEN level.[Level] = 2 THEN area.Name END AS nvarchar(200)) AS MunicipalityName,
        CAST(CASE WHEN level.[Level] = 1 THEN area.Name END AS nvarchar(200)) AS DepartmentName,
        CAST(
            CASE
                WHEN level.[Level] >= 3 THEN CONCAT(areaType.Name, N' ', area.Name)
            END
            AS nvarchar(600)) AS LocalAreaPath
    FROM dbo.AdministrativeAreas AS area
    INNER JOIN dbo.CountryAdministrativeLevels AS level
        ON level.Id = area.CountryAdministrativeLevelId
    INNER JOIN dbo.AdministrativeAreaTypes AS areaType
        ON areaType.Id = area.AdministrativeAreaTypeId
    WHERE level.CountryId = @CountryId

    UNION ALL

    SELECT
        path.AdministrativeAreaId,
        parent.ParentId,
        CAST(
            COALESCE(path.MunicipalityName, CASE WHEN parentLevel.[Level] = 2 THEN parent.Name END)
            AS nvarchar(200)),
        CAST(
            COALESCE(path.DepartmentName, CASE WHEN parentLevel.[Level] = 1 THEN parent.Name END)
            AS nvarchar(200)),
        CAST(
            CASE
                WHEN parentLevel.[Level] >= 3 THEN CONCAT(path.LocalAreaPath, N', ', parentType.Name, N' ', parent.Name)
                ELSE path.LocalAreaPath
            END
            AS nvarchar(600))
    FROM AreaPaths AS path
    INNER JOIN dbo.AdministrativeAreas AS parent
        ON parent.Id = path.ParentId
    INNER JOIN dbo.CountryAdministrativeLevels AS parentLevel
        ON parentLevel.Id = parent.CountryAdministrativeLevelId
    INNER JOIN dbo.AdministrativeAreaTypes AS parentType
        ON parentType.Id = parent.AdministrativeAreaTypeId
)
INSERT INTO #CandidateLocations (AdministrativeAreaId, DisplayName)
SELECT
    AdministrativeAreaId,
    CAST(
        CASE
            WHEN LocalAreaPath IS NOT NULL THEN CONCAT(LocalAreaPath, N', ', MunicipalityName, N', ', DepartmentName)
            WHEN MunicipalityName IS NOT NULL THEN CONCAT(MunicipalityName, N', ', DepartmentName)
            ELSE DepartmentName
        END
        AS nvarchar(600))
FROM AreaPaths
WHERE ParentId IS NULL
  AND LocalAreaPath IS NOT NULL
  AND NOT EXISTS
  (
      SELECT 1
      FROM dbo.AdministrativeAreas AS child
      WHERE child.ParentId = AreaPaths.AdministrativeAreaId
  )
OPTION (MAXRECURSION 100);

WHILE EXISTS
(
    SELECT 1
    FROM #CandidateLocations AS source
    WHERE NOT EXISTS
    (
        SELECT 1
        FROM dbo.LocationSearches AS target
        WHERE target.AdministrativeAreaId = source.AdministrativeAreaId
    )
)
BEGIN
    BEGIN TRANSACTION;

    INSERT TOP (500) INTO dbo.LocationSearches (AdministrativeAreaId, DisplayName, SearchText)
    SELECT source.AdministrativeAreaId, source.DisplayName,
        REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(LOWER(source.DisplayName), N'á', N'a'), N'é', N'e'), N'í', N'i'), N'ó', N'o'), N'ú', N'u'), N'ü', N'u'), N'ñ', N'n'), N'-', N' '), N'''', N'')
    FROM #CandidateLocations AS source
    WHERE NOT EXISTS
    (
        SELECT 1
        FROM dbo.LocationSearches AS target WITH (UPDLOCK, HOLDLOCK)
        WHERE target.AdministrativeAreaId = source.AdministrativeAreaId
    );

    COMMIT TRANSACTION;
END;
